    stream_options={"include_usage": True},
)
for chunk in stream:
    if chunk.choices and chunk.choices[0].delta.content:
        print(chunk.choices[0].delta.content, end="", flush=True)
    if chunk.usage:
        print(f"\n[{chunk.usage.completion_tokens} tokens]")

const res = await fetch("http://localhost:8000/v1/chat/completions", {
  method: "POST",
  headers: { Authorization: `Bearer ${process.env.API_KEY}`, "Content-Type": "application/json" },
  body: JSON.stringify({ model: "sonnet", stream: true, messages: [{ role: "user", content: "Write a haiku." }] }),
});
if (!res.ok) throw new Error((await res.json()).error.message); // failed before any text

const decoder = new TextDecoder();
let buffer = "";
for await (const bytes of res.body) {
  buffer += decoder.decode(bytes, { stream: true });
  let end;
  while ((end = buffer.indexOf("\n\n")) >= 0) {
    const data = buffer.slice(0, end).replace(/^data: /, "");
    buffer = buffer.slice(end + 2);
    if (data === "[DONE]") break;
    const event = JSON.parse(data);
    if (event.error) throw new Error(event.error.message); // failed part way
    process.stdout.write(event.choices[0]?.delta?.content ?? "");
  }
}

