const BASE = "http://localhost:8000/v1";
const headers = {
  Authorization: `Bearer ${process.env.API_KEY}`,
  "Content-Type": "application/json",
};

async function say(sessionId, content) {
  const res = await fetch(`${BASE}/sessions/${sessionId}/messages`, {
    method: "POST",
    headers,
    body: JSON.stringify({ content }),
  });
  const data = await res.json();
  if (!res.ok) throw new Error(data.error.message);
  return data.choices[0].message.content;
}

const { id } = await (await fetch(`${BASE}/sessions`, { method: "POST", headers, body: "{}" })).json();
console.log(await say(id, "Remember the number 42."));
console.log(await say(id, "Which number did I ask you to remember?"));

ResponseFormat.description:
`text` (default) returns free text. `json_object` adds an instruction to answer with a single JSON
object. `json_schema` passes `json_schema.schema` to `claude --json-schema` for structured output;
the reply's `content` is then the JSON document as a string.
